output_text:
[
  {
    "id": "no_cart_two_sided_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves flank both sides of the shopper.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "twoSidedShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            "singleFile"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "twoSidedShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper may not move a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_then_enter_narrow_aisle",
    "text": "After parking a cart at the mouth of a single-file shelf aisle, the shopper is obliged to enter that aisle without the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCartAtMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enterAisleWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCartAtMouth",
      "discharge": "enterAisleWithoutCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "A cart parked at the mouth of a single-file shelf aisle must eventually be retrieved before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCartAtMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "return_to_cart_after_narrow_item",
    "text": "After taking an item while standing in a single-file shelf aisle without a cart, the shopper must return and recover the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "takeNarrowAisleItem": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "takeNarrowAisleItem",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "cart_handoffs_only_in_wide_clear_corridors",
    "text": "Picking up or dropping off a cart is only allowed in wide, clear corridor cells rather than beside shelves or in constricted aisles.",
    "abstraction": {
      "state_properties": {
        "wideClearCorridor": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartDropAwayFromWideCorridor": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "wideClearCorridor"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartPickupAwayFromWideCorridor": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              {
                "not": "wideClearCorridor"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cartDropAwayFromWideCorridor",
          "cartPickupAwayFromWideCorridor"
        ]
      }
    }
  },
  {
    "id": "no_cart_free_roaming",
    "text": "Except at the cart area, at a single-file aisle mouth, or inside the single-file aisle itself, shoppers should not roam without their cart.",
    "abstraction": {
      "state_properties": {
        "cartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "allowedWithoutCart": {
          "or": [
            "cartArea",
            "singleFileShelfAisle",
            "singleFileAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "allowedWithoutCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_cart_traffic",
    "text": "Cart traffic is one-way through the store, so shoppers pushing carts are prohibited from moving west.",
    "abstraction": {
      "state_properties": {
        "pushingCart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pushingCart",
          "W"
        ]
      }
    }
  }
]
